-- ==============================================================================
-- LUNASITE — COMPLETE SUPABASE DATABASE SYNC (NASA, ISRO, CNSA, USSR, JAXA, CLPS)
-- Run this script in your Supabase SQL Editor (https://supabase.com/dashboard/project/ceasfzjikaebrrnvtamu/sql)
-- ==============================================================================

-- 1. Update Row-Level Security (RLS) to permit public INSERT/UPDATE
DROP POLICY IF EXISTS "Public read lunar missions" ON public.lunar_missions;
DROP POLICY IF EXISTS "Public read/write lunar missions" ON public.lunar_missions;
CREATE POLICY "Public read/write lunar missions" ON public.lunar_missions FOR ALL USING (true);

DROP POLICY IF EXISTS "Public read lunar features" ON public.lunar_features;
DROP POLICY IF EXISTS "Public read/write lunar features" ON public.lunar_features;
CREATE POLICY "Public read/write lunar features" ON public.lunar_features FOR ALL USING (true);

DROP POLICY IF EXISTS "Public read/write custom profiles" ON public.custom_mission_profiles;
CREATE POLICY "Public read/write custom profiles" ON public.custom_mission_profiles FOR ALL USING (true);

-- 2. Upsert Authoritative Lunar Missions (38 Missions across NASA, ISRO, CNSA, USSR, JAXA, CLPS)
ON CONFLICT (name) DO UPDATE SET
    agency = EXCLUDED.agency,
    landing_date = EXCLUDED.landing_date,
    latitude_deg = EXCLUDED.latitude_deg,
    longitude_deg = EXCLUDED.longitude_deg,
    site_name = EXCLUDED.site_name,
    status = EXCLUDED.status,
    category = EXCLUDED.category,
    description = EXCLUDED.description,
    scientific_significance = EXCLUDED.scientific_significance;

-- 3. Upsert Lunar Features & Permanently Shadowed Regions (18 Features)
ON CONFLICT (name) DO UPDATE SET
    feature_type = EXCLUDED.feature_type,
    latitude_deg = EXCLUDED.latitude_deg,
    longitude_deg = EXCLUDED.longitude_deg,
    diameter_km = EXCLUDED.diameter_km,
    depth_m = EXCLUDED.depth_m,
    permanently_shadowed = EXCLUDED.permanently_shadowed,
    ice_potential = EXCLUDED.ice_potential,
    description = EXCLUDED.description;

-- 4. Upsert Mission Profiles

-- Verification Query
SELECT 'lunar_missions' AS table_name, count(*) AS total_records FROM public.lunar_missions
UNION ALL
SELECT 'lunar_features' AS table_name, count(*) AS total_records FROM public.lunar_features
UNION ALL
SELECT 'custom_mission_profiles' AS table_name, count(*) AS total_records FROM public.custom_mission_profiles;
