INSERT INTO public.lunar_missions (name, agency, landing_date, latitude_deg, longitude_deg, site_name, status, category, description, scientific_significance)
VALUES
    ('Chandrayaan-3 (Vikram / Pragyan)', 'ISRO', '2023-08-23', -69.367621, 32.348126, 'Shiv Shakti Point', 'Historical Success', 'Lander / Rover', 'First successful soft landing in the lunar South Pole high-latitude region (69.37°S). Deployed Vikram lander and Pragyan rover. Conducted first in-situ thermal probe (ChaSTE) into regolith down to 10 cm, Langmuir probe plasma analysis (RAMBHA), and laser-induced breakdown spectroscopy (LIBS).', 'Demonstrated pinpoint landing in rugged southern terrain; verified steep vertical thermal gradient (60°C on surface to -10°C at 8 cm depth); confirmed unambiguous presence of sulfur, iron, and titanium.'),
    ('Chandrayaan-1 Moon Impact Probe (MIP)', 'ISRO', '2008-11-14', -89.76, 39.4, 'Jawahar Point (Shackleton Rim)', 'Historical Success', 'Impact Probe', 'Released from the Chandrayaan-1 orbiter and intentionally impacted near Shackleton Crater rim at the South Pole. The Chandra''s Altitudinal Composition Explorer (CHACE) quadrupole mass spectrometer directly sampled the tenuous lunar atmosphere during descent.', 'First direct, in-situ discovery of water vapor / hydroxyl (H2O / OH) molecules in the lunar polar exosphere, pioneering global lunar water-ice exploration.'),
    ('Chandrayaan-2 Vikram Lander', 'ISRO', '2019-09-06', -70.881, 22.784, 'Simpelius N Region', 'Hard Landing', 'Lander / Rover', 'High-latitude landing attempt near the South Pole. During terminal braking phase at 2.1 km altitude, software telemetry deviation caused loss of attitude control, resulting in high-velocity surface impact. Impact site identified by NASA LROC optical cameras.', 'Orbiter remains highly active in orbit, providing the highest spatial resolution lunar optical stereo imagery (0.25 m/pixel OHRC) and dual-frequency synthetic aperture radar (DFSAR) data.'),
    ('Apollo 11 (Eagle)', 'NASA', '1969-07-20', 0.67408, 23.47297, 'Statio Tranquillitatis', 'Historical Success', 'Crewed Landing', 'First crewed landing on the Moon by Neil Armstrong and Buzz Aldrin. Lunar Module Eagle touched down in southern Mare Tranquillitatis. Surface EVA duration 2h 31m. Deployed Early Apollo Scientific Experiments Package (EASEP) including passive seismometer and laser ranging retroreflector (LRRR).', 'Returned 21.55 kg of pristine lunar rock and regolith samples; determined mare basalts age (~3.7 Ga); proved human operational capability in 1/6th g gravity.'),
    ('Apollo 12 (Intrepid)', 'NASA', '1969-11-19', -3.01239, -23.42157, 'Oceanus Procellarum', 'Historical Success', 'Crewed Landing', 'First pinpoint precision lunar landing. Pete Conrad and Alan Bean landed within 160 meters of the Surveyor 3 robotic probe launched 2.5 years earlier. Deployed full Apollo Lunar Surface Experiments Package (ALSEP). Recovered parts of Surveyor 3 for Earth laboratory analysis.', 'Returned 34.35 kg of samples; confirmed precision landing radar guidance; demonstrated long-term space weathering effects on engineered alloys and optics.'),
    ('Apollo 14 (Antares)', 'NASA', '1971-02-05', -3.6453, -17.47136, 'Fra Mauro Highlands', 'Historical Success', 'Crewed Landing', 'Alan Shepard and Edgar Mitchell landed in the Fra Mauro formation, the extensive ejecta blanket deposited by the giant Imbrium basin impact. Used the Modular Equipment Transporter (MET) handcart to hike to Cone Crater rim.', 'Returned 42.28 kg of samples including Big Bertha (breccia containing ancient terrestrial impactite fragment dated 4.0 Ga); constrained the timing of the Imbrium cataclysm.'),
    ('Apollo 15 (Falcon)', 'NASA', '1971-07-30', 26.13222, 3.63386, 'Hadley-Apennine', 'Historical Success', 'Crewed Landing', 'First J-series extended exploration mission. David Scott and James Irwin utilized the first Lunar Roving Vehicle (LRV-1), traversing 27.8 km along the edge of Hadley Rille gorge and Montes Apenninus (4,500 m high mountains).', 'Discovered the ''Genesis Rock'' (anorthosite sample 15415, age 4.1 Ga), providing empirical proof of the magma ocean hypothesis and primordial lunar crust formation; returned 77.31 kg of samples.'),
    ('Apollo 16 (Orion)', 'NASA', '1972-04-21', -8.97301, 15.49812, 'Descartes Highlands', 'Historical Success', 'Crewed Landing', 'John Young and Charles Duke landed in the central lunar highlands to sample the Cayley and Descartes geological formations. Traversed 26.55 km with LRV-2, exploring Stone Mountain and North Ray Crater.', 'Conclusively refuted the prevailing hypothesis that highland plains were formed by volcanism, proving they are impact breccias formed by basin ejecta; returned 95.71 kg of ancient highland crust.'),
    ('Apollo 17 (Challenger)', 'NASA', '1972-12-11', 20.1908, 30.77168, 'Taurus-Littrow Valley', 'Historical Success', 'Crewed Landing', 'Final Apollo lunar landing mission. Geologist-astronaut Harrison Schmitt and Gene Cernan spent 75 hours on the lunar surface, completing 3 EVAs (22h 4m total) and traversing 35.74 km in LRV-3. Explored South Massif, North Massif, and Shorty Crater.', 'Discovered orange volcanic glass beads at Shorty Crater, proving explosive pyroclastic volcanism fed by deep-seated mantle volatiles; returned 110.52 kg of diverse lunar samples.'),
    ('Surveyor 1', 'NASA / JPL', '1966-06-02', -2.4745, -43.3399, 'Flamsteed Crater, Oceanus Procellarum', 'Historical Success', 'Robotic Soft Lander', 'First American soft landing on the Moon. Transmitted 11,237 high-resolution television frames of the surrounding mare landscape, crater morphology, and spacecraft footpads.', 'Demonstrated that lunar soil possessed sufficient bearing strength (30-50 kPa) to support heavy Apollo Lunar Modules, disproving the catastrophic dust ocean hypothesis.'),
    ('Surveyor 3', 'NASA / JPL', '1967-04-20', -3.016, -23.418, 'Oceanus Procellarum', 'Historical Success', 'Robotic Soft Lander', 'Landed inside a 200-meter crater. Equipped with a motorized surface-sampler scoop arm that dug four trenches up to 18 cm deep. Visited and inspected in person by Apollo 12 astronauts in November 1969.', 'First mechanical manipulation of lunar regolith; provided direct mechanical properties of highland-adjacent soil; Surveyor 3 TV camera was returned to Earth for microbiological and materials analysis.'),
    ('Surveyor 5', 'NASA / JPL', '1967-09-11', 1.461, 23.195, 'Mare Tranquillitatis', 'Historical Success', 'Robotic Soft Lander', 'Landed on a 20-degree inner slope of a small crater in Mare Tranquillitatis. Deployed an alpha-scattering instrument directly onto the lunar surface to conduct alpha backscatter and proton emission spectroscopy.', 'First direct chemical elemental analysis of extraterrestrial soil; revealed mare basalt composition rich in iron, titanium, and basaltic silicates.'),
    ('Surveyor 6', 'NASA / JPL', '1967-11-10', 0.474, -1.48, 'Sinus Medii', 'Historical Success', 'Robotic Soft Lander', 'Landed near the exact center of the Moon''s visible nearside hemisphere. On November 17, 1967, fired its vernier engines for 2.5 seconds, lifting off the lunar surface to an altitude of 3-4 meters and translating 2.5 meters laterally.', 'First liftoff from the lunar surface; analyzed undisturbed regolith at the secondary landing spot and imaged the primary landing footprint to examine rocket blast erosion.'),
    ('Surveyor 7', 'NASA / JPL', '1968-01-10', -40.857, -11.47, 'Tycho Crater Rim', 'Historical Success', 'Robotic Soft Lander', 'Only Surveyor mission sent to a rugged lunar highland region, landing 30 km north of the rim of the giant young ray crater Tycho. Deployed alpha-scattering instrument and magnetic flux density detectors.', 'First in-situ chemical analysis of lunar highlands rock; revealed significantly lower iron content and higher aluminum/calcium content than mare basalts, matching anorthositic composition.'),
    ('Luna 2', 'USSR / Lavochkin', '1959-09-13', 29.1, 0.0, 'Palus Putredinis', 'Historical Success', 'Impact Probe', 'First human-made object to reach the surface of the Moon or any other celestial body. Impacted the lunar surface east of Mare Serenitatis at 3.3 km/s carrying pennants of the Soviet Union and magnetometers.', 'Conclusively proved that the Moon has no significant dipole magnetic field (<100 gamma) and detected no evidence of trapped radiation belts around the Moon.'),
    ('Luna 9', 'USSR / Lavochkin', '1966-02-03', 7.08, -64.37, 'Oceanus Procellarum', 'Historical Success', 'Robotic Soft Lander', 'First spacecraft to accomplish a survivable soft landing on the Moon. Hermetic instrument sphere deployed 4 petal antennas and rotating telephotometer camera.', 'Transmitted first panoramic television photographs from lunar ground level; proved regolith had solid load-bearing capacity; measured surface radiation rate of 30 mrad/day.'),
    ('Luna 13', 'USSR / Lavochkin', '1966-12-24', 18.87, -62.05, 'Oceanus Procellarum', 'Historical Success', 'Robotic Soft Lander', 'Equipped with mechanical penetrometer soil-density meter and gamma-ray radiation densitometer deployed on extendable pantograph booms.', 'First in-situ physical and mechanical testing of lunar soil density (0.8 g/cm³) and bearing resistance to a depth of 5 cm.'),
    ('Luna 16', 'USSR / Lavochkin', '1970-09-20', -0.686, 56.364, 'Mare Fecunditatis', 'Historical Success', 'Robotic Sample Return', 'First automated robotic spacecraft to extract and return soil samples from an extraterrestrial body. Robotic drill extracted a 35-cm core sample into a spherical return capsule, which launched directly to Earth.', 'Returned 101 grams of lunar regolith without human crew; confirmed robotic sample recovery feasibility; samples dated to 3.4 billion years old.'),
    ('Luna 17 / Lunokhod 1', 'USSR / Lavochkin', '1970-11-17', 38.238, -35.002, 'Mare Imbrium', 'Historical Success', 'Lander / Rover', 'Delivered Lunokhod 1, the world''s first automated robotic roving vehicle on another planetary body. Powered by solar cells and polonium-210 radioisotope heater, operated for 322 Earth days (10.5 km total distance).', 'Carried out 500 lunar soil mechanical strength tests and 25 RIFMA X-ray fluorescence soil chemical analyses; transmitted over 20,000 television images and 206 panoramic views.'),
    ('Luna 20', 'USSR / Lavochkin', '1972-02-21', 3.786, 56.625, 'Apollonius Highlands', 'Historical Success', 'Robotic Sample Return', 'Second successful robotic sample return mission, landing in the rugged highland terrain between Mare Fecunditatis and Mare Crisium. Drilled into anorthositic bedrock.', 'Returned 55 grams of predominantly anorthositic highland regolith, establishing the geochemical composition of ancient lunar highlands crust.'),
    ('Luna 21 / Lunokhod 2', 'USSR / Lavochkin', '1973-01-15', 25.85, 30.45, 'Le Monnier Crater, Mare Serenitatis', 'Historical Success', 'Lander / Rover', 'Delivered Lunokhod 2 rover, which traversed 39.0 km across mare plains and highland rilles over 4 months—holding the off-world distance record for over 40 years.', 'Studied mare-highland boundary transitions, measured magnetic fields across the Fossa Recta tectonic fracture, and determined local sky luminance (albedo).'),
    ('Luna 24', 'USSR / Lavochkin', '1976-08-18', 12.714, 62.213, 'Mare Crisium', 'Historical Success', 'Robotic Sample Return', 'Final mission of the Soviet Luna series. Used an advanced rotary-percussive core drill to extract a continuous 2-meter soil core preserved inside a flexible spiral tube.', 'Returned 170 grams of layered lunar soil; in 1978, Soviet researchers published spectroscopic detection of 0.1 wt% water in Luna 24 samples, prefiguring modern lunar water discoveries.'),
    ('Chang''e 3 / Yutu', 'CNSA', '2013-12-14', 44.1214, -19.5116, 'Mare Imbrium (Guang Han Gong)', 'Historical Success', 'Lander / Rover', 'First lunar soft landing in 37 years. Deployed the Yutu rover equipped with ground-penetrating radar (GPR) and the Lunar-based Ultraviolet Telescope (LUT) on the lander.', 'Identified a new type of lunar basalt with intermediate titanium and rich iron oxide; GPR mapped structural subsurface regolith layering down to 400 meters depth.'),
    ('Chang''e 4 / Yutu-2', 'CNSA', '2019-01-03', -45.457, 177.588, 'Von Kármán Crater (SPA Basin)', 'Historical Success', 'Lander / Rover', 'First ever soft landing on the farside of the Moon, communicating via the Queqiao halo orbit relay satellite at Earth-Moon L2. Yutu-2 rover has traversed over 1.6 km on the farside.', 'Sampled deep excavated mantle material within the South Pole-Aitken (SPA) basin; conducted low-frequency radio astronomy unhindered by terrestrial ionospheric noise.'),
    ('Chang''e 5', 'CNSA', '2020-12-01', 43.0576, -51.9161, 'Mons Rümker / Statio Tianchuan', 'Historical Success', 'Robotic Sample Return', 'Complex four-element architecture (Orbiter, Lander, Ascender, Returner). Drilled and scooped samples from young northern Oceanus Procellarum, automated orbital rendezvous, and Earth return.', 'Returned 1,731 grams of samples; radiometrically dated basalt samples to 2.03 billion years old, proving the Moon remained volcanically active 1 billion years longer than previously believed.'),
    ('Chang''e 6', 'CNSA', '2024-06-01', -41.6385, -153.9852, 'Apollo Crater (SPA Basin)', 'Historical Success', 'Robotic Sample Return', 'First ever successful sample return mission from the farside of the Moon. Landed in the southern Apollo impact crater within the SPA basin using Queqiao-2 relay satellite.', 'Returned 1,935.3 grams of farside regolith; provides direct physical samples to unravel the Moon''s fundamental nearside-farside crustal dichotomy and ancient volcanic history.'),
    ('SLIM (Smart Lander for Investigating Moon)', 'JAXA', '2024-01-19', -13.316, 25.251, 'Shioli Crater', 'Historical Success', 'Robotic Precision Lander', 'Demonstrated ultra-precise ''pinpoint'' landing using vision-based crater pattern matching navigation, touching down within ~55 meters of target on a 15-degree crater slope. Deployed LEV-1 and LEV-2 (SORA-Q) micro-rovers.', 'Achieved unprecedented landing accuracy (<100 m vs standard several km ellipses); multi-band camera analyzed olivine composition excavated from lunar mantle.'),
    ('LCROSS (Centaur & Shepherding Spacecraft)', 'NASA', '2009-10-09', -84.675, -48.725, 'Cabeus Crater Floor', 'Historical Success', 'Impact Science Mission', 'Centaur upper stage impacted Cabeus crater floor at 2.5 km/s, creating a 20-meter crater and excavating a plume of debris. The following Shepherding Spacecraft flew through the plume with 9 spectrometers before impacting 4 minutes later.', 'Definitively detected 155 ± 12 kg of water ice and OH volatiles (5.6 ± 2.9 wt% water vapor/ice in ejecta plume), alongside carbon monoxide, methane, ammonia, and sulfur volatiles in a South Pole cold trap.'),
    ('IM-1 Odysseus (CLPS Nova-C)', 'Intuitive Machines / NASA CLPS', '2024-02-22', -80.13, 1.44, 'Malapert A', 'Historical Success', 'CLPS Commercial Lander', 'First commercial spacecraft to execute a soft landing on the Moon, and first American lunar touchdown since Apollo 17 in 1972. Landed ~300 km from the South Pole. Operated NASA commercial payloads including ROLSES radio receiver and NDL navigation doppler lidar.', 'Validated commercial lunar lander payload delivery; measured space weather radio emissions and demonstrated autonomous cryogenic methane/oxygen propulsion.'),
    ('Blue Ghost Mission 1', 'Firefly Aerospace / NASA CLPS', '2025-03-02', 18.56, 61.81, 'Mare Crisium', 'Planned Target', 'CLPS Commercial Lander', 'Carrying 10 NASA-sponsored payloads to Mare Crisium. Scheduled to study lunar regolith properties, Earth''s magnetosphere interaction, solar wind radiation, and thermal conductivity.', 'Comprehensive geophysical and space-environment characterization of Mare Crisium basin.'),
    ('IM-2 Athena (CLPS Nova-C)', 'Intuitive Machines / NASA CLPS', '2025-03-06', -89.45, 222.05, 'Connecting Ridge (Shackleton)', 'Planned Target', 'CLPS Commercial Polar Lander', 'NASA CLPS mission carrying the PRIME-1 (Polar Resources Ice Mining Experiment-1) drill and MSolo mass spectrometer directly to the Shackleton connecting ridge to drill 1 meter into lunar cryo-soil.', 'First active in-situ robotic drilling and extraction of subsurface polar ice volatiles.'),
    ('Artemis III Candidate: Connecting Ridge', 'NASA', '2026-10-01', -89.44, 222.05, 'Shackleton-de Gerlache Connecting Ridge', 'Candidate Target', 'Crewed Artemis Corridor', 'Premier Artemis candidate region. Topographic ridge connecting Shackleton and de Gerlache craters features extreme solar illumination (>80% annual sunlight) and immediate access to deep PSR cold traps.', 'Co-locates persistent solar power generation with cryogenic ice traps for in-situ resource utilization (ISRU) water harvesting.'),
    ('Artemis III Candidate: Peak Near Shackleton', 'NASA', '2026-10-01', -89.7, 122.9, 'Peak Near Shackleton', 'Candidate Target', 'Crewed Artemis Corridor', 'High ridge overlooking the Shackleton crater floor. Provides steep line-of-sight elevation for continuous Direct-to-Earth communication and long-duration solar illumination during southern lunar summer.', 'High-altitude vantage point for communication relays and polar traverse staging.'),
    ('Artemis III Candidate: Haworth Rim', 'NASA', '2026-10-01', -87.9, -5.1, 'Haworth Crater Rim', 'Candidate Target', 'Crewed Artemis Corridor', 'Promontory along the rim of Haworth crater. Deeply shadowed interior cold traps are among the coldest measured environments in the solar system (<40 Kelvin).', 'Exploration of pristine volatile preservation zones containing ancient cometary and asteroid volatile deposits.'),
    ('Artemis III Candidate: Malapert Massif', 'NASA', '2026-10-01', -86.0, 2.7, 'Malapert Mountain Crest', 'Candidate Target', 'Crewed Artemis Corridor', 'Peak of Eternal Light candidate standing 5,000 meters above surrounding topography. Features near-constant annual solar visibility and unbroken line-of-sight communication to Earth.', 'Prime candidate for base-camp infrastructure, nuclear/solar power hubs, and telecommunications towers.'),
    ('Artemis III Candidate: Faustini Rim A', 'NASA', '2026-10-01', -87.2, 114.3, 'Faustini Rim A Plateau', 'Candidate Target', 'Crewed Artemis Corridor', 'Broad elevated plateau on the eastern rim of Faustini crater offering low slope landing terrain (<5°) and direct access to permanently shadowed floor volatiles.', 'Safe touchdown zone for heavy human landers with low slope hazard and stable regolith.'),
    ('Artemis III Candidate: Nobile Rim 1', 'NASA', '2026-10-01', -85.2, 37.5, 'Nobile Crater Rim', 'Candidate Target', 'Crewed Artemis Corridor', 'Mountainous rim region near Nobile crater. Surface exhibits a mosaic of micro-cold traps interspersed with sunlight plateaus, identified as high-priority exploration targets.', 'High concentration of hydrogen signatures detected by orbital neutron spectrometers.'),
    ('Artemis III Candidate: Amundsen Rim', 'NASA', '2026-10-01', -84.5, 65.7, 'Amundsen Crater Rim Ridge', 'Candidate Target', 'Crewed Artemis Corridor', 'Northern rim of the 105-km diameter Amundsen impact crater. Features expansive terraced walls and diverse geological contacts between South Pole-Aitken basin ejecta and highland units.', 'Exposure of excavated deep crustal rocks and extensive permanently shadowed ice deposits.')
INSERT INTO public.lunar_features (name, feature_type, latitude_deg, longitude_deg, diameter_km, depth_m, permanently_shadowed, ice_potential, description)
VALUES
    ('Shackleton Crater', 'Crater / PSR', -89.9, 0.0, 21.0, 4200.0, TRUE, 'CRITICAL', 'Located exactly at the Lunar South Pole. Peaks on its rim experience nearly perpetual sunlight (>86%), while the interior floor has been frozen in permanent shadow for over two billion years at temperatures below 90 Kelvin.'),
    ('Cabeus Crater', 'Crater / PSR', -84.9, -35.5, 100.0, 4000.0, TRUE, 'CONFIRMED (LCROSS)', 'Site of NASA''s 2009 LCROSS impact experiment, which excavated and spectroscopically confirmed water vapor, ice crystals (5.6 wt%), hydroxyl, methane, ammonia, and light hydrocarbons.'),
    ('Haworth Crater', 'Crater / PSR', -87.4, -5.1, 35.0, 3800.0, TRUE, 'VERY HIGH', 'Deep South Pole cold trap with lowest measured surface temperatures in the Solar System (<40 Kelvin by LRO Diviner radiometer). Unbroken thermal stability since basin formation.'),
    ('Shoemaker Crater', 'Crater / PSR', -88.1, 44.9, 51.0, 3500.0, TRUE, 'VERY HIGH', 'Named after planetary geologist Eugene Shoemaker. Subsurface epithermal neutron absorption indicates substantial hydrogen enrichment consistent with subsurface water ice deposits.'),
    ('Faustini Crater', 'Crater / PSR', -87.3, 77.0, 39.0, 3200.0, TRUE, 'VERY HIGH', 'Extensive permanently shadowed area adjacent to elevated, highly illuminated rim ridges. Prime candidate target for long-range Artemis rover traverses.'),
    ('de Gerlache Crater', 'Crater / PSR', -88.5, -87.1, 32.4, 3100.0, TRUE, 'HIGH', 'Rims form the connecting ridge between Shackleton and de Gerlache craters. Exhibits high annual solar illumination alongside immediate proximity to permanently shadowed cryo-traps.'),
    ('Amundsen Crater', 'Crater / PSR', -84.5, 82.8, 105.0, 4800.0, TRUE, 'CONFIRMED', 'Large complex impact crater with prominent central peaks and extensive floor cold traps containing surface frost patches detected by LRO Lyman-Alpha Mapping Project (LAMP).'),
    ('Nobile Crater', 'Crater / PSR', -85.2, 53.5, 73.0, 3700.0, TRUE, 'CONFIRMED (VIPER Target)', 'Target exploration region for NASA''s Volatiles Investigating Polar Exploration Rover (VIPER). Features a mosaic of illuminated ridges and micro-cold traps holding shallow subsurface volatiles.'),
    ('Malapert Mountain (Massif)', 'Mountain Massif', -86.04, 2.7, 60.0, -5000.0, FALSE, 'LOW (Solar Power Node)', 'Massive topographic high near the South Pole with continuous Direct-to-Earth communication visibility and very high annual solar illumination (>88%). Prime communications and power hub.'),
    ('Mons Mouton (Leibnitz Beta)', 'Lunar Plateau / Mountain', -84.5, 31.0, 100.0, -6000.0, FALSE, 'MODERATE (High Sun)', 'Flat-topped lunar mountain standing 6 km above surrounding terrain. Long continuous periods of direct sunlight and unobstructed line-of-sight for Earth communication.'),
    ('Aristarchus Plateau', 'Plateau / Pyroclastic', 23.7, -47.4, 170.0, -2000.0, FALSE, 'NONE (Mineral / Volcanic)', 'Volcanically rich elevated plateau with Vallis Schröteri sinuous rille, high concentrations of radioactive thorium, and regional pyroclastic glass deposits rich in ilmenite.'),
    ('Tycho Crater', 'Impact Crater', -43.31, -11.36, 85.0, 4800.0, FALSE, 'NONE', 'Prominent young (~108 Ma) Copernican impact crater with central peak and extensive bright ray system stretching over 1,500 km across the lunar nearside.'),
    ('Copernicus Crater', 'Impact Crater', 9.62, -20.08, 93.0, 3800.0, FALSE, 'NONE', 'Benchmark crater defining the Copernican lunar geological period. Features majestic terraced rim walls, multi-peak central mountain complex, and olivine-bearing impact melts.'),
    ('South Pole-Aitken (SPA) Basin', 'Impact Basin', -53.0, 169.0, 2500.0, 8200.0, FALSE, 'HIGH (Southern Depressions)', 'Largest, oldest (~4.3 Ga), and deepest impact structure on the Moon, spanning across the southern farside. Impact excavated deeply into lower crust and upper mantle strata.'),
    ('Marius Hills Hole (Skylight)', 'Lava Tube / Volcanic', 14.09, -56.77, 0.065, 80.0, TRUE, 'LOW (Subsurface Shelter)', 'Subsurface lava tube skylight entrance discovered by SELENE and LROC. Offers natural thermal buffering (~ -20°C constant) and shielding against galactic cosmic rays and micrometeoroids.'),
    ('Reiner Gamma', 'Swirl / Magnetic Anomaly', 7.5, -59.0, 60.0, 0.0, FALSE, 'NONE (Magnetic Field)', 'High-albedo lunar swirl co-located with a strong localized magnetic crustal anomaly that deflects charged solar wind ions, shielding the underlying regolith from space weathering.'),
    ('Mare Tranquillitatis', 'Lunar Mare', 8.5, 31.4, 873.0, 0.0, FALSE, 'NONE (High-Ti Basalt)', 'Extensive basaltic flood plain characterized by high titanium content (up to 15 wt% TiO2 in ilmenite). Site of Apollo 11 historical landing.'),
    ('Oceanus Procellarum', 'Lunar Ocean / Mare', 18.4, -57.4, 2500.0, 0.0, FALSE, 'NONE (KREEP Basalt)', 'Vast lunar mare on the western nearside hemisphere, containing elevated heat-producing radioactive elements and KREEP (potassium, rare earth elements, phosphorus) basalts.')
INSERT INTO public.custom_mission_profiles (name, description, weights_json)
VALUES
    ('Polar Water-Ice Prospecting', 'Optimized for cryogenic rover/lander missions targeting volatile deposits and water ice inside South Pole cold traps (PSRs). High weight on cold-trap proximity and radar/thermal accessibility.', '{"illumination_weight": 0.2, "comm_weight": 0.15, "slope_weight": 0.25, "psr_proximity_weight": 0.4, "max_acceptable_slope_deg": 12.0}'::jsonb),
    ('Solar-Powered Surface Base', 'Prioritizes high annual solar illumination on elevated polar peaks and massifs for continuous photovoltaic power generation and minimal night-cycle battery requirements.', '{"illumination_weight": 0.5, "comm_weight": 0.25, "slope_weight": 0.2, "psr_proximity_weight": 0.05, "max_acceptable_slope_deg": 10.0}'::jsonb),
    ('Radio Astronomy Farside Observatory', 'Prioritizes lunar farside sites with 100% terrain shielding from terrestrial radio frequency interference (RFI) for pristine cosmological ultra-long wavelength radio observations.', '{"illumination_weight": 0.25, "comm_weight": 0.05, "slope_weight": 0.3, "psr_proximity_weight": 0.1, "rf_quiet_weight": 0.3, "max_acceptable_slope_deg": 8.0}'::jsonb),
    ('Crewed Artemis Base Camp', 'NASA Artemis Human Landing System (HLS) safety specifications: low touchdown slope (<8°), continuous Direct-to-Earth communication, high sunlight (>70%), and accessible ISRU water ice.', '{"illumination_weight": 0.3, "comm_weight": 0.3, "slope_weight": 0.25, "psr_proximity_weight": 0.15, "max_acceptable_slope_deg": 8.0}'::jsonb),
    ('Commercial Robotic Cargo Lander (CLPS)', 'Commercial payload landing profile: prioritizes hazard minimization (flat topography, slope < 6°) and maximum geometric Direct-to-Earth visibility for high-bandwidth telemetry.', '{"illumination_weight": 0.3, "comm_weight": 0.35, "slope_weight": 0.3, "psr_proximity_weight": 0.05, "max_acceptable_slope_deg": 6.0}'::jsonb);
